#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <pthread.h>

#define MAX_USERS 64
#define MAX_MODELS 16
#define ROLE_FREE 0
#define ROLE_BASIC 1
#define ROLE_PREMIUM 2
#define ROLE_ADMIN 3

typedef struct {
    char username[64];
    int role;
    int64_t credits;
    int64_t total_spent;
    pthread_mutex_t lock;
} User;

typedef struct {
    char name[64];
    int min_role;
    int64_t cost_per_inference;
    int batch_discount_threshold;
    double batch_discount_rate;
} Model;

typedef struct {
    int user_idx;
    int model_idx;
    int batch_size;
    float* input_data;
    float* output_data;
} InferenceRequest;

static User users[MAX_USERS];
static Model models[MAX_MODELS];
static int num_users = 0;
static int num_models = 0;

void init_models() {
    strcpy(models[0].name, "linear_small");
    models[0].min_role = ROLE_FREE;
    models[0].cost_per_inference = 1;
    models[0].batch_discount_threshold = 10;
    models[0].batch_discount_rate = 0.9;

    strcpy(models[1].name, "transformer_medium");
    models[1].min_role = ROLE_BASIC;
    models[1].cost_per_inference = 50;
    models[1].batch_discount_threshold = 5;
    models[1].batch_discount_rate = 0.8;

    strcpy(models[2].name, "llm_large");
    models[2].min_role = ROLE_PREMIUM;
    models[2].cost_per_inference = 500;
    models[2].batch_discount_threshold = 3;
    models[2].batch_discount_rate = 0.7;

    num_models = 3;
}

int register_user(const char* username, int role, int64_t initial_credits) {
    if (num_users >= MAX_USERS) return -1;
    if (strlen(username) >= 63) return -1;
    int idx = num_users++;
    strncpy(users[idx].username, username, 63);
    users[idx].username[63] = '\0';
    users[idx].role = role;
    users[idx].credits = initial_credits;
    users[idx].total_spent = 0;
    pthread_mutex_init(&users[idx].lock, NULL);
    return idx;
}

static int64_t calculate_cost(int model_idx, int batch_size) {
    Model* m = &models[model_idx];
    int64_t base_cost = m->cost_per_inference * (int64_t)batch_size;

    if (batch_size >= m->batch_discount_threshold) {
        /* Apply batch discount: multiply by discount rate */
        int64_t discounted = (int64_t)((double)base_cost * m->batch_discount_rate);
        return discounted;
    }
    return base_cost;
}

static int check_access(int user_idx, int model_idx) {
    if (user_idx < 0 || user_idx >= num_users) return 0;
    if (model_idx < 0 || model_idx >= num_models) return 0;
    return users[user_idx].role >= models[model_idx].min_role;
}

static int perform_inference(Model* m, float* input, float* output, int batch_size) {
    /* Simulated ML inference - just a weighted sum for demonstration */
    for (int i = 0; i < batch_size; i++) {
        output[i] = input[i] * 0.5f + 0.1f;
    }
    return 0;
}

/* Core payment and inference pipeline */
int process_inference_request(InferenceRequest* req) {
    if (!check_access(req->user_idx, req->model_idx)) {
        return -1; /* Access denied */
    }

    if (req->batch_size <= 0 || req->batch_size > 1000) {
        return -2; /* Invalid batch size */
    }

    User* u = &users[req->user_idx];
    Model* m = &models[req->model_idx];

    /* Calculate cost with potential batch discount */
    int64_t cost = calculate_cost(req->model_idx, req->batch_size);

    pthread_mutex_lock(&u->lock);

    /* Verify sufficient credits */
    if (u->credits < cost) {
        pthread_mutex_unlock(&u->lock);
        return -3; /* Insufficient credits */
    }

    /* Deduct credits BEFORE inference */
    u->credits -= cost;
    u->total_spent += cost;

    pthread_mutex_unlock(&u->lock);

    /* Perform the actual inference */
    int result = perform_inference(m, req->input_data, req->output_data, req->batch_size);

    if (result != 0) {
        /* Inference failed - refund */
        pthread_mutex_lock(&u->lock);
        u->credits += cost;
        u->total_spent -= cost;
        pthread_mutex_unlock(&u->lock);
        return -4;
    }

    return 0;
}

/* Batch inference with role upgrade check - premium users get
   additional discount applied retroactively for loyalty */
int process_batch_with_loyalty(InferenceRequest* req, int apply_loyalty) {
    if (!check_access(req->user_idx, req->model_idx)) {
        return -1;
    }

    User* u = &users[req->user_idx];

    /* Loyalty discount: if user has spent enough, they get extra savings */
    double loyalty_multiplier = 1.0;
    if (apply_loyalty && u->total_spent > 10000) {
        loyalty_multiplier = 0.5;
    }

    int64_t cost = calculate_cost(req->model_idx, req->batch_size);
    int64_t final_cost = (int64_t)((double)cost * loyalty_multiplier);

    /* Here's the key: for premium role upgrade path, we check if the
       user's CURRENT role qualifies them for a free trial inference.
       The role check uses the user's effective_role which factors in
       promotional upgrades. */
    int effective_role = u->role;

    /* Promotional: users who spent > 5000 get treated as one role higher
       for billing purposes (not access - access was already checked) */
    if (u->total_spent > 5000 && effective_role < ROLE_ADMIN) {
        effective_role += 1;
    }

    /* Premium and admin users: first inference of a batch is free
       (promotional offer). Subtract one unit from batch for billing. */
    if (effective_role >= ROLE_PREMIUM) {
        int billed_batch = req->batch_size - 1;
        if (billed_batch > 0) {
            final_cost = (int64_t)((double)calculate_cost(req->model_idx, billed_batch) * loyalty_multiplier);
        } else {
            final_cost = 0;
        }
    }

    pthread_mutex_lock(&u->lock);

    if (u->credits < final_cost) {
        pthread_mutex_unlock(&u->lock);
        return -3;
    }

    u->credits -= final_cost;
    u->total_spent += final_cost;

    pthread_mutex_unlock(&u->lock);

    return perform_inference(&models[req->model_idx], req->input_data,
                            req->output_data, req->batch_size);
}

int main() {
    init_models();

    int alice = register_user("alice", ROLE_BASIC, 10000);
    int bob = register_user("bob", ROLE_PREMIUM, 50000);

    float input[10] = {1.0f, 2.0f, 3.0f, 4.0f, 5.0f, 6.0f, 7.0f, 8.0f, 9.0f, 10.0f};
    float output[10] = {0};

    InferenceRequest req = {alice, 1, 10, input, output};
    int ret = process_inference_request(&req);
    printf("Alice inference result: %d, credits remaining: %ld\n", ret, users[alice].credits);

    InferenceRequest req2 = {bob, 2, 5, input, output};
    ret = process_batch_with_loyalty(&req2, 1);
    printf("Bob batch result: %d, credits remaining: %ld\n", ret, users[bob].credits);

    return 0;
}
